select mo.id, mo.order_no, mo.request_no, su.user_name, mo.user_id, mo.assigned_agent_id, mo.platform_code, mo.platform_name, mo.total_count, mo.success_count, mo.failed_count, mo.total_amount, mo.refund_amount, mo.order_status, mo.audit_status, mo.audit_opinion, mo.audit_by, mo.audit_time, mo.completed_time, mo.create_by, mo.create_time, mo.update_by, mo.update_time, mo.remark, ( select moi.phone from mark_order_item moi where moi.order_id = mo.id order by case when moi.process_status = '0' then 0 else 1 end, moi.id asc limit 1 ) as phone_preview from mark_order mo left join sys_user su on su.user_id = mo.user_id
and ( mo.assigned_agent_id = #{agentId} or (mo.assigned_agent_id is null and su.create_by = #{agentUsername}) or exists ( select 1 from sys_user agent_u inner join sys_user_role aur on aur.user_id = agent_u.user_id inner join sys_role ar on ar.role_id = aur.role_id and ar.role_key in ('agent', 'mark_agent') where agent_u.user_id = #{agentId} and agent_u.del_flag = '0' and agent_u.rel_mark_template is not null and agent_u.rel_mark_template > 0 and su.rel_mark_template = agent_u.rel_mark_template ) or exists ( select 1 from mark_platform_template mpt where mpt.id = su.rel_mark_template and mpt.owner_user_id = #{agentId} and mpt.status = '0' ) )
and mo.order_no like concat('%', #{query.orderNo}, '%')
and mo.request_no like concat('%', #{query.requestNo}, '%')
and ( mo.order_no like concat('%', #{query.keyword}, '%') or su.user_name like concat('%', #{query.keyword}, '%') or exists ( select 1 from mark_order_item moi where moi.order_id = mo.id and moi.phone like concat('%', #{query.keyword}, '%') ) )
and mo.user_id = #{query.userId}
and mo.platform_code = #{query.platformCode}
and mo.order_status = #{query.orderStatus}
and mo.audit_status = #{query.auditStatus}
and mo.audit_status in ('1','2','3')
and mo.id in ( select moi.order_id from mark_order_item moi where moi.phone like concat('%', #{query.phone}, '%') )
and mo.create_time >= #{query.params.beginTime}
and mo.create_time <= concat(#{query.params.endTime}, ' 23:59:59')
order by mo.create_time desc

select mo.id
from mark_order mo
where mo.user_id = #{userId}
  and mo.request_no = #{requestNo}
limit 1

