order_no = #{orderNo}, request_no = #{requestNo}, user_id = #{userId}, assigned_agent_id = #{assignedAgentId}, platform_code = #{platformCode}, platform_name = #{platformName}, total_count = #{totalCount}, success_count = #{successCount}, failed_count = #{failedCount}, total_amount = #{totalAmount}, refund_amount = #{refundAmount}, order_status = #{orderStatus}, audit_status = #{auditStatus}, audit_opinion = #{auditOpinion}, audit_by = #{auditBy}, audit_time = #{auditTime}, completed_time = #{completedTime}, update_by = #{updateBy}, update_time = #{updateTime}, remark = #{remark},
